head.script:
scwin.onpageload = function() {
	autoComplete1.setValue("t2");
};
scwin.checkVal1 = function() {
	return (document.getElementById('autoComplete1_input') || document.getElementById('mf_autoComplete1_input')).getAttribute('aria-activedescendant') === null;
};
scwin.checkVal2 = function() {
	return (document.getElementById('autoComplete1_arrow') || document.getElementById('mf_autoComplete1_arrow')).getAttribute('href') === null;
};
scwin.checkVal3 = function() {
	return (document.getElementById('autoComplete1_itemTable') || document.getElementById('mf_autoComplete1_itemTable')).getAttribute('aria-expanded') === null;
};
